from functools import wraps

def trace(function):
    @wraps(function)
    def wrapper(*args, **kwargs):
        print(f"calling {function.__name__}")
        result = function(*args, **kwargs)
        print(f"result: {result}")
        return result
    return wrapper

@trace
def add(left, right):
    return left + right

print(add(2, 3))
```

The decorator runs once when `add` is defined; the returned wrapper's body runs whenever `add` is called.

```python
from functools import wraps
from inspect import signature

def logged(function):
    @wraps(function)
    def wrapper(*args, **kwargs):
        return function(*args, **kwargs)
    return wrapper

@logged
def greet(name: str) -> str:
    """Return a friendly greeting."""
    return f"Hello, {name}!"

print(greet.__name__)       # greet
print(greet.__doc__)        # Return a friendly greeting.
print(signature(greet))     # (name: str) -> str
print(greet("Ada"))
```

The program calls the wrapper, while metadata-aware tools can still describe the public `greet` function.

```python
from functools import wraps

def repeat(*, times):
    if times < 1:
        raise ValueError("times must be positive")

    def decorator(function):
        @wraps(function)
        def wrapper(*args, **kwargs):
            result = None
            for _ in range(times):
                result = function(*args, **kwargs)
            return result
        return wrapper

    return decorator

@repeat(times=3)
def announce(message):
    print(message)
    return len(message)

print(announce("Ready"))  # prints Ready three times, then 5
```

The repeat count is retained when the decorator is applied; the message arrives later when the wrapper is called.
